PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, login TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS questions (id TEXT PRIMARY KEY, origin TEXT NOT NULL CHECK(origin IN ('school','ai')), unit TEXT NOT NULL, kind TEXT NOT NULL, current_version TEXT NOT NULL, position INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS question_versions (id TEXT PRIMARY KEY, question_id TEXT NOT NULL REFERENCES questions(id), content_hash TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), grading TEXT NOT NULL CHECK(json_valid(grading)), tags TEXT NOT NULL CHECK(json_valid(tags)), gradable INTEGER NOT NULL CHECK(gradable IN (0,1)), created_at TEXT NOT NULL, UNIQUE(question_id,content_hash));
CREATE TABLE IF NOT EXISTS assets (path TEXT PRIMARY KEY, mime TEXT NOT NULL, bytes BLOB NOT NULL, content_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rounds (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), cycle INTEGER NOT NULL, number INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','complete','cleared')), created_at TEXT NOT NULL, completed_at TEXT, UNIQUE(user_id,cycle,number));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_round ON rounds(user_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS round_items (round_id TEXT NOT NULL REFERENCES rounds(id), question_id TEXT NOT NULL REFERENCES questions(id), version_id TEXT NOT NULL REFERENCES question_versions(id), position INTEGER NOT NULL, PRIMARY KEY(round_id,question_id), UNIQUE(round_id,position));
CREATE TABLE IF NOT EXISTS attempts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), context_type TEXT NOT NULL CHECK(context_type IN ('round','practice','review')), context_id TEXT NOT NULL, question_id TEXT NOT NULL REFERENCES questions(id), version_id TEXT NOT NULL REFERENCES question_versions(id), response TEXT NOT NULL CHECK(json_valid(response)), duration_ms INTEGER NOT NULL CHECK(duration_ms>=0), created_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_round_answer ON attempts(user_id,context_id,question_id) WHERE context_type='round';
CREATE UNIQUE INDEX IF NOT EXISTS one_practice_answer ON attempts(user_id,context_id,question_id) WHERE context_type='practice';
CREATE INDEX IF NOT EXISTS attempts_user_date ON attempts(user_id,created_at);
CREATE INDEX IF NOT EXISTS attempts_question ON attempts(user_id,question_id);
CREATE TABLE IF NOT EXISTS evaluations (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT UNIQUE NOT NULL, attempt_id TEXT NOT NULL REFERENCES attempts(id), verdict TEXT NOT NULL CHECK(verdict IN ('pending','needs_review','correct','incorrect')), score REAL, method TEXT NOT NULL CHECK(method IN ('rule','ai','manual')), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL);
CREATE VIEW IF NOT EXISTS effective_attempts AS SELECT a.*, e.verdict, e.score, e.method, e.data AS evaluation_data, e.seq AS evaluation_seq FROM attempts a JOIN evaluations e ON e.seq=(SELECT MAX(e2.seq) FROM evaluations e2 WHERE e2.attempt_id=a.id);
CREATE TABLE IF NOT EXISTS review_debts (user_id TEXT NOT NULL REFERENCES users(id), question_id TEXT NOT NULL REFERENCES questions(id), version_id TEXT NOT NULL REFERENCES question_versions(id), created_at TEXT NOT NULL, PRIMARY KEY(user_id,question_id));
CREATE TABLE IF NOT EXISTS drafts (user_id TEXT NOT NULL REFERENCES users(id), context_type TEXT NOT NULL, context_id TEXT NOT NULL, question_id TEXT NOT NULL, response TEXT NOT NULL, elapsed_ms INTEGER NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(user_id,context_type,context_id,question_id));
CREATE TABLE IF NOT EXISTS practice_sets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, mode TEXT NOT NULL, origin TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('generating','draft','ready','failed')), conditions TEXT NOT NULL CHECK(json_valid(conditions)), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS practice_items (set_id TEXT NOT NULL REFERENCES practice_sets(id), question_id TEXT NOT NULL REFERENCES questions(id), version_id TEXT NOT NULL REFERENCES question_versions(id), position INTEGER NOT NULL, verification TEXT NOT NULL CHECK(json_valid(verification)), PRIMARY KEY(set_id,question_id), UNIQUE(set_id,position));
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('grade','generate','verify')), payload TEXT NOT NULL CHECK(json_valid(payload)), status TEXT NOT NULL CHECK(status IN ('pending','running','deferred','done','failed')), tries INTEGER NOT NULL DEFAULT 0, lease_until TEXT, next_at TEXT NOT NULL, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(status,next_at);
CREATE TABLE IF NOT EXISTS ai_usage (day TEXT PRIMARY KEY, reserved_neurons INTEGER NOT NULL DEFAULT 0, calls INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS imports (id TEXT PRIMARY KEY, question_count INTEGER NOT NULL, gradable_count INTEGER NOT NULL, image_count INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mastery_cache (user_id TEXT NOT NULL, question_id TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), updated_at TEXT NOT NULL, PRIMARY KEY(user_id,question_id));
